export const operations=["inspect", "inspect_abilities", "inspect_resources", "inspect_vitality", "activate_ability", "aim_ability", "aim_ability_at", "cancel_ability", "inspect_navigation", "inspect_npcs", "inspect_relations", "inspect_targeting", "inspect_knowledge", "inspect_hearing", "inspect_objectives", "inspect_territory", "inspect_passages", "inspect_mobility", "set_ability_catalog", "set_spatial_network", "set_passages", "set_faction_relations", "inspect_noises", "inspect_footsteps", "inspect_patrols", "inspect_triggers", "inspect_selection", "select_entity", "select_at", "set_debug_view", "emit_noise", "generate", "edit_scene", "upsert", "remove", "set_camera", "set_light", "undo", "redo", "play", "pause", "reset", "set_input", "step", "events", "save_scenario", "inspect_scenario", "run_scenario", "save_scene", "load_scene", "save_replay", "run_replay", "inspect_replay", "capture_replay", "capture", "exit"];
export const systems=[{"group": "world", "title": ["Scenes with an origin", "Cenas que guardam sua origem"], "body": ["Versioned JSON scenes, stable IDs and rooms generated from a recipe and seed. Parameters and provenance travel with the result.", "Cenas JSON versionadas, IDs estáveis e salas geradas por receita e semente. Parâmetros e proveniência acompanham o resultado."], "limit": ["The current generator creates rooms; the cross-system procedural framework is on the roadmap.", "O gerador atual cria salas; o framework procedural transversal ainda está no roadmap."], "commands": ["generate", "save_scene", "load_scene"]}, {"group": "world", "title": ["Edit with a way back", "Editar sem perder o caminho de volta"], "body": ["Typed batch edits, validation before commit, final-state reference checks, expected revisions and transactional undo/redo. Authored documents stay separate from simulation.", "Edições tipadas em lote, validação antes de aplicar, referências verificadas no estado final, revisão esperada e undo/redo em uma transação. Documento autoral e simulação permanecem separados."], "limit": ["Undo reverses authorship, not physics time. Applied edits restart the paused simulation.", "Undo reverte autoria, não o tempo da física. Edições aplicadas reiniciam a simulação pausada."], "commands": ["edit_scene", "upsert", "remove", "undo", "redo"]}, {"group": "world", "title": ["Physics in explicit steps", "Física em passos explícitos"], "body": ["Fixed 60 Hz simulation, Rapier bodies and collisions, gravity, shared input, walking, running and stealth. Run freely or advance exact ticks.", "Simulação fixa a 60 Hz, corpos e colisões Rapier, gravidade, entrada compartilhada, caminhada, corrida e furtividade. Execute livremente ou avance ticks exatos."], "limit": ["Ramps and steps have a separate study; an integrated controller is still ahead.", "Rampas e degraus têm um estudo separado; ainda não são um controlador integrado."], "commands": ["play", "pause", "reset", "set_input", "step"]}, {"group": "world", "title": ["A visible, selectable world", "Um mundo visível e selecionável"], "body": ["Native and offscreen 3D rendering, perspective camera, directional and ambient light, grid, ID or pixel selection and current-object outlines.", "Renderização 3D nativa e offscreen, câmera em perspectiva, luz direcional e ambiente, grade, seleção por ID ou pixel e contorno do objeto atual."], "limit": ["PBR, shadows, asset import, gizmos and the full editor are planned.", "PBR, sombras, importação de assets, gizmos e editor completo estão planejados."], "commands": ["set_camera", "set_light", "select_entity", "select_at", "inspect_selection", "capture"]}, {"group": "world", "title": ["Volumes that detect passage", "Volumes que percebem passagem"], "body": ["AABB triggers, explicit targets, post-physics entry and exit, and bounded event history. Visibility can change independently of collision or perception.", "Gatilhos AABB, alvos explícitos, entrada e saída após a física e histórico limitado de eventos. Visibilidade pode mudar sem alterar colisão ou percepção."], "limit": ["Current volumes are fixed and unrotated; detection is discrete.", "Volumes atuais são fixos e sem rotação; detecção discreta."], "commands": ["inspect_triggers", "events"]}, {"group": "minds", "title": ["Seeing is not knowing everything", "Ver não é saber tudo"], "body": ["Volumetric XYZ vision with yaw and pitch, range, field of view and occlusion. Gradual per-individual confirmation separates suspicion from recognition and memory.", "Visão volumétrica XYZ com yaw e pitch, alcance, campo visual e oclusão. Confirmação gradual por indivíduo separa suspeita de reconhecimento e memória."], "limit": ["Sensor orientation does not animate the body. Omniscience is an explicit policy only.", "Orientação sensorial não anima o corpo. Onisciência só existe como política explícita."], "commands": ["inspect_npcs", "inspect_knowledge", "set_debug_view"]}, {"group": "minds", "title": ["Hear a clue. Not a live coordinate.", "Ouvir uma pista. Não uma coordenada viva."], "body": ["Anonymous noises with frozen positions, acoustic transmission, attention arbitration and visual-memory protection. Physical footsteps reflect speed and locomotion profile.", "Ruídos anônimos com posição congelada, transmissão acústica, arbitragem de atenção e proteção da memória visual. Passos físicos refletem velocidade e perfil de locomoção."], "limit": ["Hearing events are gameplay; audio playback is a future system.", "Eventos de audição são gameplay; reprodução de áudio é um sistema futuro."], "commands": ["emit_noise", "inspect_hearing", "inspect_noises", "inspect_footsteps"]}, {"group": "minds", "title": ["Autonomy, relationships and targets", "Autonomia, relações e alvos"], "body": ["NPCs can operate without targeting the player, perceive other NPCs and select observed hostiles. Factions, directional attitudes and hysteresis govern eligibility and switching.", "NPCs podem existir sem jogador como alvo, perceber outros NPCs e selecionar hostis observados. Facções, atitudes direcionais e histerese controlam elegibilidade e troca."], "limit": ["Eligibility never supplies a hidden location.", "Elegibilidade nunca fornece a localização oculta de alguém."], "commands": ["set_faction_relations", "inspect_relations", "inspect_targeting"]}, {"group": "minds", "title": ["Memory, search and communication", "Memória, busca e comunicação"], "body": ["Last known positions, expiry, search hypotheses and explicit budgets. Allies can share confirmed observations through channels, XYZ radius and preserved TTL.", "Última posição conhecida, expiração, hipóteses de busca e budgets explícitos. Aliados podem compartilhar observações confirmadas por canal, raio XYZ e TTL preservado."], "limit": ["Reports do not cascade; a search hypothesis never becomes a real observation.", "Relatos não se propagam em cascata; hipótese de busca não vira observação real."], "commands": ["inspect_knowledge", "inspect_hearing", "inspect_npcs"]}, {"group": "minds", "title": ["Decisions that explain themselves", "Decisões que explicam seus motivos"], "body": ["Composable objectives with priorities and conditions: respond, flee, patrol, guard, wait and use abilities. Interruption and resumption preserve authorized knowledge.", "Objetivos componíveis com prioridade e condições: responder, fugir, patrulhar, guardar, esperar e usar habilidades. Interrupção e retomada preservam o conhecimento autorizado."], "limit": ["This is a bounded objective selector, not yet a general behavior framework.", "É um seletor de objetivos limitado, ainda não um framework geral de comportamento."], "commands": ["inspect_objectives", "inspect_npcs"]}, {"group": "minds", "title": ["Routines with a place in the world", "Rotinas com lugar no mundo"], "body": ["Authored or generated XYZ patrols, loop and ping-pong, waiting and resumption. Circular territory limits clue acquisition and commits physical return to origin.", "Patrulhas XYZ autoradas ou geradas, loop e ping-pong, espera e retomada. Território circular limita aquisição de pistas e compromete retorno físico à origem."], "limit": ["Territory is a planar behavioral boundary. Needs, schedules and 3D territory remain planned.", "Território é um limite comportamental planar. Necessidades, agendas e território 3D seguem no plano."], "commands": ["inspect_patrols", "inspect_territory"]}, {"group": "minds", "title": ["Find a route. Share a passage.", "Encontrar caminho. Dividir passagem."], "body": ["Planar A*, partial routes, recovery with waiting and physical progress. Explicit passages have exclusive reservations, queues, aging, deadlines and physical entry gates.", "A* planar, rotas parciais, recuperação com espera e progresso físico. Passagens explícitas têm reserva exclusiva, fila, aging, prazo e gate de entrada físico."], "limit": ["Navmesh, automatic bottleneck discovery and general crowd solving are still ahead.", "Ainda não há navmesh, descoberta automática de gargalos ou solução geral de multidões."], "commands": ["inspect_navigation", "set_passages", "inspect_passages"]}, {"group": "minds", "title": ["Movement in three dimensions", "Movimento que ocupa três dimensões"], "body": ["XYZ spatial network with walk, jump, glide and fly capabilities; local connections, modular-floor support and partial approaches. Curved flight limits acceleration and turning, with hover and orbit.", "Rede espacial XYZ com capacidades walk, jump, glide e fly; conexões locais, apoio sobre pisos modulares e aproximação parcial. Voo curvado limita aceleração e giro, com hover e órbita."], "limit": ["Connectivity is explicit; this is not free-space aerial navigation or full aerodynamics.", "Conectividade é explícita; não é navegação aérea livre nem aerodinâmica completa."], "commands": ["set_spatial_network", "inspect_mobility", "inspect_navigation"]}, {"group": "actions", "title": ["Abilities, one shared executor", "Habilidades, um executor compartilhado"], "body": ["Player and NPC share one executor: scaled integer resources, atomic costs, casts, cooldowns and cancellation. Movement can remain free, interrupt or be locked by a cast.", "Jogador e NPC usam o mesmo executor: recursos inteiros com escala, custos atômicos, cast, cooldown e cancelamento. Movimento pode ser livre, interromper ou ser bloqueado pelo cast."], "limit": ["NPC policies revalidate conditions and evidence; an approach does not guarantee a viable route.", "Políticas de NPC revalidam condições e evidência; aproximação não garante caminho viável."], "commands": ["set_ability_catalog", "activate_ability", "cancel_ability", "inspect_abilities", "inspect_resources"]}, {"group": "actions", "title": ["Life, damage, healing and consequences", "Vida, dano, cura e consequências"], "body": ["Vitality independent of grants, transactional effects and final death within an execution. Death cancels casts and reservations while preserving body, gravity and inertia.", "Vitalidade independente dos grants, efeitos transacionais e morte final na execução. Morte cancela casts e reservas, preservando corpo, gravidade e inércia."], "limit": ["There is no implicit resurrection or respawn; memory does not reveal a hidden death.", "Não há ressurreição ou respawn implícito; memória não revela uma morte oculta."], "commands": ["inspect_vitality", "inspect_abilities"]}, {"group": "actions", "title": ["Projectiles and spatial intent", "Projéteis e intenção espacial"], "body": ["Straight XYZ projectiles with AABB sweeps and first contact. Aim by direction, point or cursor on an explicit plane; automatic aim uses confirmed, frozen visual evidence.", "Projéteis XYZ retilíneos com sweep AABB e primeiro contato. Mira por direção, ponto ou cursor em plano explícito; mira automática usa evidência visual confirmada e congelada."], "limit": ["Homing, ballistics, target prediction, area effects and tactical dodging are still ahead.", "Sem homing, balística, previsão do alvo, área ou esquiva tática."], "commands": ["aim_ability", "aim_ability_at", "activate_ability", "inspect_abilities"]}, {"group": "actions", "title": ["Effects that persist. Rules that dispel.", "Efeitos que persistem. Regras que dissipam."], "body": ["Periodic damage, healing and resources, bounded schedules, refresh or independent executions. Category- and limit-based dispelling with atomic costs and removal at commit or impact.", "Dano, cura e recursos periódicos, agendas limitadas, renovação ou execuções independentes. Dissipação por categoria e limite, com custo e remoção atômicos no commit ou impacto."], "limit": ["General modifiers, multiple tags, immunities, channeling and areas remain planned.", "Modificadores gerais, múltiplas tags, imunidades, canalização e áreas continuam planejados."], "commands": ["inspect_abilities", "inspect_resources", "inspect_vitality"]}, {"group": "evidence", "title": ["The contract is the interface", "O contrato é a interface"], "body": ["Shared typed dispatcher, command-derived schemas and structured results. MCP over stdio and native controls reach the same API. Projects run without the agent that created them.", "Dispatcher tipado compartilhado, schemas derivados dos comandos e resultados estruturados. MCP via stdio e controles nativos chegam à mesma API. Projetos executam sem o agente que os criou."], "limit": ["MCP is the control plane; simulation advances internally without an AI call per frame.", "MCP é o plano de controle; a simulação avança internamente, sem uma chamada de IA por frame."], "commands": ["inspect", "exit"]}, {"group": "evidence", "title": ["Inspect beyond appearances", "Inspecionar além da aparência"], "body": ["Queryable state, sources, reasons, resources, routes and decisions. Vision, hearing, noise and route guides, vitality bars and captures through the same renderer.", "Estado, fontes, motivos, recursos, caminhos e decisões consultáveis. Guias de visão, audição, ruído e rotas, barras de vida e capturas pelo mesmo renderizador."], "limit": ["Developer inspection does not enter NPC knowledge.", "A inspeção do desenvolvedor não entra no conhecimento dos NPCs."], "commands": ["inspect", "set_debug_view", "capture", "events"]}, {"group": "evidence", "title": ["Reproduce. Verify. Refine.", "Reproduzir. Verificar. Corrigir."], "body": ["Tick-inspectable replay and isolated captures without changing the live session. Scenarios with typed checks, finite budgets and reports distinguishing behavior failures from transport errors.", "Replay inspecionável por tick e captura isolada sem alterar a partida viva. Cenários com checks tipados, orçamento finito e relatório que distingue falha de comportamento de erro de transporte."], "limit": ["Replay requires the same build; cross-platform determinism is not a current guarantee.", "Replay exige o mesmo build; determinismo entre plataformas não é uma garantia atual."], "commands": ["save_replay", "run_replay", "inspect_replay", "capture_replay", "save_scenario", "inspect_scenario", "run_scenario"]}];
export const roadmap=[{"id": "M01", "title": ["Core & extensibility", "Núcleo e extensibilidade"], "now": ["Rust runtime, identity, events and versioned formats.", "Runtime Rust, identidade, eventos e formatos versionados."], "next": ["Composable modules, lifecycle, loading and cross-language contracts. External extensions with persistent state; WebAssembly is a candidate, with no approved contract yet.", "Módulos componíveis, ciclo de vida, carregamento e contratos entre linguagens. Extensões externas com estado persistente; WebAssembly é candidato, ainda sem contrato aprovado."]}, {"id": "M02", "title": ["Scenes, assets & editor", "Cenas, assets e editor"], "now": ["Transactional editing, selection, history, camera and saved scenes.", "Edição transacional, seleção, histórico, câmera e cenas salvas."], "next": ["Hierarchy, transforms, references and reusable scenes; glTF/GLB import, gizmos and a complete visual editor. Build, save and reopen through human controls or MCP with parity and reversal.", "Hierarquia, transformações, referências e cenas reutilizáveis; importação glTF/GLB, gizmos e editor visual completo. Montar, salvar e reabrir pelo humano ou MCP com paridade e reversão."]}, {"id": "M03", "title": ["Rendering, input, audio & UI", "Render, entrada, áudio e UI"], "now": ["Basic native/offscreen 3D rendering, lighting, input and guides.", "Render 3D básico nativo/offscreen, iluminação, entrada e guias."], "next": ["Meshes, PBR, textures, shadows, transparency and cameras. Configurable keyboard, mouse and controller actions; positional audio, music, HUD and UI. Accessible captures and metrics.", "Malhas, PBR, texturas, sombras, transparência e câmeras. Teclado, mouse e controle com ações configuráveis; áudio posicional, música, HUD e interface. Capturas e métricas acessíveis."]}, {"id": "M04", "title": ["Physics & characters", "Física e personagens"], "now": ["Gravity, collisions, triggers and terrestrial/spatial motors.", "Gravidade, colisões, gatilhos e motores terrestres e espaciais."], "next": ["Expand bodies, colliders, raycasts and queries; character control, ground, ramps, steps, jumps and obstacle interaction in reproducible scenarios. Controller integration remains a future decision.", "Expandir corpos, colisores, raycasts e consultas; controle de personagens, chão, rampas, degraus, salto e interação com obstáculos em cenários reproduzíveis. Integração do controlador ainda será decidida."]}, {"id": "M05", "title": ["Animation & avatars", "Animação e avatares"], "now": ["", ""], "next": ["Skeletons, clips, transitions and blending. Composable avatars with bodies, appearance, equipment and capabilities; rig-compatible procedural variants and animated actions.", "Esqueletos, clipes, transições e blend. Avatares componíveis com corpo, aparência, equipamento e capacidades; variações procedurais compatíveis com rig e ações animadas."]}, {"id": "M06", "title": ["Procedural generation & topology", "Proceduralidade e topologia"], "now": ["Seeded room recipe with provenance; generatable routes.", "Receita de sala com semente e proveniência; rotas geráveis."], "next": ["Cross-system framework of composable generators: parameters, constraints, seeds, provenance, partial regeneration and preserved manual edits. Geometry, meshes, surfaces and terrain with connectivity validation.", "Framework transversal de geradores componíveis: parâmetros, restrições, sementes, proveniência, regeneração parcial e preservação de edição manual. Geometria, malhas, superfícies e terrenos com validação de conectividade."]}, {"id": "M07", "title": ["Particles, water & atmosphere", "Partículas, água e atmosfera"], "now": ["", ""], "next": ["Emitters, curves, forces, collisions and events. Water surfaces and volumes, waves, currents and buoyancy. Sky, atmosphere, sun and moon, clouds, fog, weather and time cycles, controllable through MCP.", "Emissores, curvas, forças, colisões e eventos. Água em superfícies e volumes, ondas, correntes e flutuação. Céu, atmosfera, sol e lua, nuvens, neblina, clima e ciclo temporal, controláveis pelo MCP."]}, {"id": "M08", "title": ["Abilities & combat", "Habilidades e combate"], "now": ["Resources, casts, vitality, projectiles, periodic effects and dispelling.", "Recursos, cast, vitalidade, projéteis, efeitos periódicos e dissipação."], "next": ["Expanded composition of conditions, targets, costs, timing, effects, interruption and chaining. Defense, resistances, areas, melee and regeneration. Demonstrate shooting, magic and non-combat actions through one contract.", "Composição ampliada de condições, alvos, custos, tempos, efeitos, interrupções e encadeamento. Defesa, resistências, áreas, corpo a corpo e regeneração. Provar tiro, magia e ação não combativa pelo mesmo contrato."]}, {"id": "M09", "title": ["NPCs & navigation", "NPCs e navegação"], "now": ["Perception, memory, communication, objectives, routines, relationships and XYZ locomotion.", "Percepção, memória, comunicação, objetivos, rotinas, relações e locomoção XYZ."], "next": ["This early roadmap snapshot focused on NPCs: more composable decisions, routines and needs, expanded navigation and coordination, abilities, animated bodies, dialogue, population and persistence. Integrate guard, civilian, ally and creature; verifiable limited knowledge, reasons and replay. Language models remain optional, under a future contract.", "Concluir o sistema de NPCs é a prioridade atual: decisões mais componíveis, rotinas e necessidades, navegação e coordenação ampliadas, habilidades, corpo animado, diálogo, população e persistência. Integrar guarda, civil, aliado e criatura; conhecimento limitado, motivos e replay verificáveis. Modelos de linguagem opcionais, contrato futuro."]}, {"id": "M10", "title": ["Spawn & populations", "Spawn e populações"], "now": ["", ""], "next": ["Regions, waves, conditions, schedules and population budgets. Lifecycles, respawn and procedural appearance/removal rules; inspectable state and reproducible behavior.", "Regiões, ondas, condições, programação temporal e orçamento de população. Ciclos de vida, respawn e regras procedurais de surgimento e desaparecimento; estado inspecionável e comportamento reproduzível."]}, {"id": "M11", "title": ["Quests & questlines", "Quests e questlines"], "now": ["", ""], "next": ["Conditions, objectives, dependencies, branches and rewards. Individual or shared state and procedural composition; authoring, execution, inspection and persistence through one contract.", "Condições, objetivos, dependências, ramificações e recompensas. Estado individual ou compartilhado e composição procedural; autoria, execução, inspeção e persistência pelo mesmo contrato."]}, {"id": "M12", "title": ["Single-player, multiplayer & co-op", "Single-player, multiplayer e coop"], "now": ["", ""], "next": ["Authority and replication, player join/leave, headless servers, persistence and reconnection. Validate cooperative sessions; scale and network topology will be defined by scope, without an implicit MMO promise.", "Autoridade e replicação, entrada e saída de jogadores, servidor sem janela, persistência e reconexão. Validar sessões cooperativas; escala e topologia de rede serão definidas por recorte, sem promessa implícita de MMO."]}, {"id": "M13", "title": ["Open worlds & levels", "Mundo aberto e níveis"], "now": ["", ""], "next": ["Regions, streaming, transitions, instances and persistence. Procedural world assembly and coordinated system loading; state continuity between areas and sessions.", "Regiões, streaming, transições, instâncias e persistência. Montagem procedural de mundos e carregamento coordenado dos sistemas; continuidade de estado entre áreas e sessões."]}, {"id": "M14", "title": ["Dungeons, raids, PvP & PvE", "Dungeons, raids, PvP e PvE"], "now": ["", ""], "next": ["Encounters, bosses, groups, instances, checkpoints, difficulty and rewards. Factions, objectives, eligibility, scoring and victory. Reuse combat, spawn, quests and sessions; group sizes remain to be defined.", "Encontros, chefes, grupos, instâncias, checkpoints, dificuldade e recompensas. Facções, objetivos, elegibilidade, placar e vitória. Reutilizar combate, spawn, quests e sessões; escala de grupos a definir."]}, {"id": "M15", "title": ["Observation, tests & replay", "Observação, testes e replay"], "now": ["Headless simulation, captures, inspection, events, replay and typed scenarios.", "Simulação headless, captura, inspeção, eventos, replay e cenários tipados."], "next": ["Expand snapshots, diagnostics, metrics and failure reproduction. Jobs, cancellation and checkpoints remain open. Demonstrate failure → evidence → fix → passing scenario, with documented determinism boundaries.", "Ampliar snapshots, diagnósticos, métricas e reprodução de falhas. Jobs, cancelamento e checkpoints seguem abertos. Demonstrar o ciclo falha → evidência → correção → cenário passando, com limites de determinismo documentados."]}, {"id": "M16", "title": ["Games, export & source availability", "Jogos, exportação e código disponível"], "now": ["Runnable laboratories, documentation and architecture decisions.", "Laboratórios executáveis, documentação e decisões de arquitetura."], "next": ["A complete small 3D game and examples across genres. Standalone export, documentation, contribution and the commercial source license, with its profit-based royalty. Humans must play and intervene without AI dependency; publication is a separate delivery.", "Um pequeno jogo 3D completo e exemplos de gêneros distintos. Exportação independente, documentação, contribuição e licença comercial de código disponível, com participação no lucro. Humanos devem jogar e intervir sem depender de IA; publicação será uma entrega própria."]}];
